        save()
        return generation
    }

    /// İndiki nişan (yoxdursa nil) və onun nəsil nömrəsi.
    func current() -> (mark: ConsentMark?, generation: Int) {
        lock.lock()
        defer { lock.unlock() }
        return (mark: mark, generation: generation)
    }

